  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "Absolute oral bioavailability of GSK1322322 1500 mg tablet was 77% in healthy volunteers in the fed state, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Betaxolol absolute bioavailability was 87.5 ± 7.9% after a 10-mg oral capsule versus IV in 12 subjects, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "AZD0837 absolute bioavailability was 22–55% in healthy young male volunteers; even the lower bound is above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All 10 evidence molecules have numeric absolute or systemic bioavailability values at or above 20%, with most well above; assay-transfer scores are high and the evidence is predominantly direct absolute bioavailability measurements, so high F is supported.",
  "evidence_gaps": [
    "Molecule 1 groups records for GSK1322322 and brigatinib; the brigatinib record C24 was discounted as a provenance conflict.",
    "Encainide has a wide reported F range (7–82%) and some qualitative low-bioavailability reports, but the strongest absolute measurement in normal subjects is 32 ± 7%.",
    "ONO-4641 F = 0.710 is a predicted human simulation value rather than a measured bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

